# Crohn's disease / IBD medicines (19 Nov 2026, owner's request).
V, C, U, R, VR = ("v", "Very common", "more than 1 in 10"), ("c", "Common", "1 in 10 to 1 in 100"), ("u", "Uncommon", "1 in 100 to 1 in 1,000"), ("r", "Rare", "1 in 1,000 to 1 in 10,000"), ("vr", "Very rare", "fewer than 1 in 10,000")
def g(t, items): return (t[0], t[1], t[2], items)
PBS = "https://www.pbs.gov.au/pbs/search?term="
CCA = ("Crohn’s & Colitis Australia", "https://crohnsandcolitis.org.au/")
REL = [("Crohn’s disease", "/crohns-disease/"), ("Ulcerative colitis", "/ulcerative-colitis/")]
BIO_COST = ("Cost", "PBS-subsidised for moderate to severe IBD under specialist (gastroenterologist) criteria")
BIO_TIPS = ["Before starting: screening for tuberculosis, hepatitis B and C and HIV, and catch-up vaccines.", "Avoid live vaccines (e.g. yellow fever, some shingles and travel vaccines) unless your specialist says otherwise.", "Tell your doctors before surgery, and if you get a fever or infection.", "Most biologics can be continued in pregnancy after discussion with your gastroenterologist."]

med("mesalazine", "Mesalazine (Aminosalicylates): Uses in Colitis and Crohn's",
 "Mesalazine and other aminosalicylates (sulfasalazine, balsalazide) explained: first-line for ulcerative colitis, limited role in Crohn's, tablets, granules and enemas, kidney checks and side effects.",
 "Mesalazine and aminosalicylates", "Mesalazine",
 [("s", "5-aminosalicylate (5-ASA)"), ("l", "Prescription only (S4)")],
 "The mainstay for mild to moderate ulcerative colitis, acting directly on the bowel lining. Much less useful in Crohn’s disease.",
 "Mesalazine calms inflammation in the bowel lining. It treats flares and keeps ulcerative colitis in remission, as tablets, granules, suppositories or enemas. In Crohn’s disease the evidence is weak, so it’s rarely the main treatment.",
 [("For", "Ulcerative colitis (induction and maintenance); occasionally mild Crohn’s colitis"),
  ("Works", "Well in mild to moderate ulcerative colitis; little benefit in Crohn’s"),
  ("Cost", "PBS: up to $25 a script ($7.70 concession)"),
  ("Kicks in", "2 to 4 weeks"),
  ("Dose", "Often 2 to 4.8 g daily by mouth, once daily is fine; plus rectal forms for distal disease"),
  ("Watch for", "Headache, nausea; rarely kidney inflammation or a flare-like reaction")],
 "Colitis workhorse, Crohn’s bystander.",
 ["Mesalazine: Salofalk, Pentasa, Mezavant, Asacol. Sulfasalazine: Salazopyrin. Balsalazide: Colazide. Olsalazine: Dipentum"],
 "It acts topically on the bowel lining to reduce inflammatory chemical production.",
 ["Ulcerative colitis: flares and maintenance", "Proctitis (suppositories)", "Sulfasalazine also treats inflammatory arthritis"],
 "Usually well tolerated.",
 [g(C, ["Headache", "Nausea, tummy pain", "Rash"]), g(U, ["Worsening diarrhoea (intolerance can mimic a flare)"]), g(R, ["<b>Kidney inflammation</b> (interstitial nephritis)", "Pancreatitis", "Inflammation of the heart lining", "Low blood counts (sulfasalazine)"])],
 ["Fever, rash and worsening diarrhoea after starting", "Chest pain", "Severe tummy pain"],
 ["Kidney function blood tests before starting and then yearly.", "Rectal forms work best for disease in the lower bowel.", "Sulfasalazine can turn urine and contact lenses orange and lowers sperm count (reversible)."],
 [("Is mesalazine used for Crohn’s disease?", "Rarely. It works well for ulcerative colitis but has little benefit in most Crohn’s disease."),
  ("Do I need blood tests on mesalazine?", "Yes, kidney function tests before starting and usually yearly."),
  ("Can I take mesalazine once a day?", "Yes, once-daily dosing works as well as divided doses for most people.")],
 [CCA, ("PBS: Mesalazine", PBS + "mesalazine")], REL)

med("budesonide-ibd", "Budesonide for Crohn's Disease (Entocort, Cortiment): Gut-Targeted Steroid",
 "Oral budesonide for Crohn's disease and colitis explained: a gut-targeted steroid for flares in the ileum and right colon, fewer side effects than prednisolone, and why it's short term.",
 "Budesonide for IBD", "Budesonide (oral)",
 [("s", "Gut-targeted corticosteroid"), ("l", "Prescription only (S4)")],
 "A steroid released in the bowel and largely broken down by the liver, so it calms ileal Crohn’s flares with fewer body-wide side effects than prednisolone.",
 "Oral budesonide treats mild to moderate Crohn’s disease affecting the end of the small bowel and right colon (Entocort), and some ulcerative colitis (Cortiment). Most is inactivated by the liver on first pass, so steroid side effects are fewer. It’s for flares, not long-term maintenance.",
 [("For", "Mild to moderate ileal and right-sided Crohn’s flares; some ulcerative colitis; microscopic colitis"),
  ("Works", "Induces remission in about half; slightly less potent than prednisolone"),
  ("Cost", "PBS: up to $25 a script ($7.70 concession)"),
  ("Kicks in", "1 to 4 weeks"),
  ("Dose", "Commonly 9 mg once daily for 8 weeks, then tapered"),
  ("Watch for", "Fewer, but still possible, steroid effects: mood, sleep, acne")],
 "Prednisolone’s gentler cousin.",
 ["Entocort (Crohn’s), Cortiment (ulcerative colitis), Budenofalk"],
 "Released in the ileum and colon, it acts on the gut lining, then the liver breaks down about 90% before it reaches the body.",
 ["Ileal and ileocaecal Crohn’s disease flares", "Mild to moderate ulcerative colitis (Cortiment)", "Microscopic colitis (very effective)"],
 "Steroid side effects are less common than with prednisolone.",
 [g(C, ["Headache", "Acne, rounded face (less than prednisolone)", "Mood or sleep changes"]), g(U, ["High blood sugar", "Bone loss with repeated courses"]), g(R, ["Adrenal suppression after long use"])],
 ["Severe mood changes", "Signs of infection", "Worsening bleeding or pain"],
 ["Swallow capsules whole in the morning.", "Avoid grapefruit (raises levels).", "It’s for flares: ask about a long-term maintenance plan if you need repeated courses."],
 [("Is budesonide better than prednisolone for Crohn’s?", "It has fewer side effects but is slightly less powerful, and only works for disease in the ileum and right colon."),
  ("Can I stay on budesonide long term?", "It isn’t recommended for long-term maintenance in Crohn’s. Repeated courses mean a steroid-sparing treatment is needed."),
  ("Why avoid grapefruit with budesonide?", "Grapefruit blocks the liver enzyme that breaks budesonide down, increasing side effects.")],
 [CCA, ("PBS: Budesonide", PBS + "budesonide")], REL + [("Prednisolone", "/medicines/prednisolone/")])

med("thiopurines", "Azathioprine and Mercaptopurine: Thiopurines for Crohn's and Colitis",
 "Azathioprine (Imuran) and mercaptopurine (Puri-Nethol) explained: keeping Crohn's and colitis in remission, TPMT testing, blood tests, skin cancer and infection risks, and use with biologics.",
 "Azathioprine and mercaptopurine (thiopurines)", "Thiopurines",
 [("s", "Immunomodulator"), ("l", "Prescription only (S4)")],
 "Steroid-sparing tablets that keep IBD in remission, alone or alongside a biologic. Slow to work, and need regular blood tests.",
 "Thiopurines dampen the immune response over months. They help people stay off steroids and, combined with infliximab, improve results and reduce antibodies against it. A TPMT/NUDT15 test before starting finds people who need lower doses.",
 [("For", "Maintaining remission in Crohn’s disease and ulcerative colitis; combined with anti-TNF biologics"),
  ("Works", "Steroid-free remission in many; slow onset"),
  ("Cost", "PBS: up to $25 a script ($7.70 concession)"),
  ("Kicks in", "3 to 6 months"),
  ("Dose", "Azathioprine about 2 to 2.5 mg/kg daily; mercaptopurine about 1 to 1.5 mg/kg daily; guided by TPMT and metabolite levels"),
  ("Watch for", "Nausea, flu-like symptoms early; infections, low blood counts")],
 "Slow, steady, blood-test dependent.",
 ["Azathioprine: Imuran, Azapin. Mercaptopurine: Puri-Nethol. Thioguanine (specialist use)"],
 "They become thioguanine nucleotides that slow the multiplication of immune cells.",
 ["Maintenance in Crohn’s disease and ulcerative colitis", "With infliximab or adalimumab to reduce antibodies", "Autoimmune hepatitis and other autoimmune conditions"],
 "Most side effects appear in the first weeks; blood tests catch the important ones.",
 [g(C, ["Nausea, vomiting", "Flu-like illness", "Abnormal liver tests"]), g(U, ["<b>Low white cells</b>", "<b>Pancreatitis</b> (usually in the first month)", "Infections"]), g(R, ["<b>Non-melanoma skin cancer</b> (higher with long use)", "<b>Lymphoma</b> (small absolute increase)"])],
 ["Fever, sore throat or mouth ulcers", "Severe upper tummy pain (pancreatitis)", "Yellow skin or dark urine"],
 ["Blood tests weekly at first, then every 3 months.", "Use sun protection and have yearly skin checks.", "Never combine with allopurinol unless your specialist adjusts the dose (dangerous interaction).", "Avoid live vaccines."],
 [("Why do I need a TPMT test before azathioprine?", "About 1 in 300 people has very low TPMT activity and can get dangerously low blood counts on standard doses. The test guides the dose."),
  ("How long does azathioprine take to work?", "Usually 3 to 6 months."),
  ("Does azathioprine cause cancer?", "It slightly increases skin cancer and lymphoma risk. Sun protection and skin checks are important; your specialist weighs this against the benefits.")],
 [CCA, ("PBS: Azathioprine", PBS + "azathioprine")], REL + [("Methotrexate", "/medicines/methotrexate/"), ("Anti-TNF biologics", "/medicines/anti-tnf-biologics/")])

med("anti-tnf-biologics", "Infliximab and Adalimumab (Anti-TNF Biologics) for Crohn's and Colitis",
 "Anti-TNF biologics explained: infliximab infusions and adalimumab injections for Crohn's disease and ulcerative colitis, biosimilars, screening, infection risk, levels and antibodies.",
 "Infliximab and adalimumab (anti-TNF)", "Anti-TNF biologics",
 [("s", "Biologic (TNF blocker)"), ("l", "Prescription only (S4), specialist")],
 "The first biologics for IBD, and still among the most effective, especially for fistulising Crohn’s. Infliximab is a drip; adalimumab is a self-injection.",
 "Anti-TNF drugs block tumour necrosis factor, a key driver of gut inflammation. They induce and maintain remission, heal the bowel lining and fistulas, and reduce surgery. Biosimilars (cheaper copies) work the same. The body can make antibodies against them, so drug levels are sometimes checked.",
 [("For", "Moderate to severe Crohn’s disease (including fistulas) and ulcerative colitis"),
  ("Works", "Remission in roughly a third to half at a year; best early in disease"),
  BIO_COST,
  ("Kicks in", "2 to 8 weeks"),
  ("Dose", "Infliximab: IV at weeks 0, 2, 6, then every 8 weeks (or under-skin injections). Adalimumab: injection every 1 to 2 weeks"),
  ("Watch for", "Infections, infusion or injection reactions")],
 "The original gut firefighter.",
 ["Infliximab: Remicade, Inflectra, Renflexis, Remsima (incl. under-skin form). Adalimumab: Humira, Hadlima, Hyrimoz, Amgevita, Yuflyma. Golimumab (Simponi) for colitis"],
 "They bind TNF-alpha, switching off a central inflammatory pathway.",
 ["Moderate to severe Crohn’s disease, including perianal fistulas", "Moderate to severe ulcerative colitis", "Also rheumatoid arthritis, psoriasis, ankylosing spondylitis and uveitis"],
 "Infection risk is the main concern.",
 [g(C, ["Infections (colds, sinus, chest, urine)", "Infusion or injection-site reactions", "Headache"]), g(U, ["Psoriasis-like rashes (paradoxical)", "Abnormal liver tests"]), g(R, ["<b>TB reactivation</b> and serious infections", "<b>Lymphoma</b> (mainly with thiopurine combination)", "Demyelination, drug-induced lupus, heart failure worsening"])],
 ["Fever, night sweats, persistent cough or weight loss", "Shortness of breath or swelling in heart failure", "Numbness, weakness or vision changes"],
 BIO_TIPS + ["Combining infliximab with azathioprine reduces antibodies and improves response."],
 [("What is the difference between infliximab and adalimumab?", "Both block TNF. Infliximab is usually an IV infusion every 8 weeks (an under-skin form now exists); adalimumab is a self-injection every 1 to 2 weeks."),
  ("Are biosimilars as good as the original?", "Yes. Biosimilars are approved as equivalent and are widely used in Australia."),
  ("Why are drug levels checked?", "Low levels or antibodies can explain loss of response, guiding a dose change or switch.")],
 [CCA, ("PBS: Infliximab", PBS + "infliximab"), ("PBS: Adalimumab", PBS + "adalimumab")], REL + [("Thiopurines", "/medicines/thiopurines/")])

med("vedolizumab", "Vedolizumab (Entyvio): Gut-Selective Biologic for Crohn's and Colitis",
 "Vedolizumab explained: a gut-selective biologic for ulcerative colitis and Crohn's disease, infusions or injections, slower onset, and a favourable infection profile.",
 "Vedolizumab", "Vedolizumab",
 [("s", "Biologic (anti-integrin)"), ("l", "Prescription only (S4), specialist")],
 "A biologic that stops inflammatory cells entering the gut, so it works mainly in the bowel with little effect on the rest of the immune system.",
 "Vedolizumab blocks the α4β7 integrin that guides white cells into the bowel wall. It’s effective for ulcerative colitis and Crohn’s disease, particularly in older people or those worried about infections. It can take longer to work than anti-TNF drugs.",
 [("For", "Moderate to severe ulcerative colitis and Crohn’s disease"),
  ("Works", "Good in colitis; moderate in Crohn’s; better earlier in disease"),
  BIO_COST,
  ("Kicks in", "6 to 14 weeks"),
  ("Dose", "IV 300 mg at weeks 0, 2, 6, then every 8 weeks; or under-skin injections every 2 weeks after induction"),
  ("Watch for", "Colds, headache, joint aches")],
 "Gut-only bouncer.",
 ["Entyvio"],
 "It blocks α4β7 integrin on white cells, stopping them homing to the gut.",
 ["Ulcerative colitis", "Crohn’s disease", "Pouchitis (specialist use)"],
 "Well tolerated; serious infections are uncommon.",
 [g(C, ["Colds and sore throat", "Headache", "Joint pain", "Nausea"]), g(U, ["Infusion reactions", "Gut infections"]), g(R, ["Serious infections", "Liver problems"])],
 ["Fever or signs of serious infection", "Yellow skin or dark urine"],
 BIO_TIPS,
 [("Is vedolizumab safer than other biologics?", "It acts mainly in the gut, so its infection risk is generally lower, but all biologics need screening and care."),
  ("How long does vedolizumab take to work?", "Often 6 to 14 weeks, sometimes longer in Crohn’s disease."),
  ("Can vedolizumab be given as an injection?", "Yes, after initial infusions an under-the-skin form can be used.")],
 [CCA, ("PBS: Vedolizumab", PBS + "vedolizumab")], REL)

med("il-12-23-biologics", "Ustekinumab, Risankizumab and Mirikizumab: IL-23 Biologics for IBD",
 "IL-12/23 and IL-23 biologics for Crohn's disease and colitis explained: ustekinumab (Stelara), risankizumab (Skyrizi), mirikizumab (Omvoh) and guselkumab (Tremfya), dosing, effectiveness and safety.",
 "Ustekinumab and IL-23 biologics", "IL-23 biologics",
 [("s", "Biologic (interleukin blocker)"), ("l", "Prescription only (S4), specialist")],
 "Biologics that block interleukin-23, a key inflammation signal in Crohn’s and colitis. An IV start, then injections every 4 to 8 weeks, with a good safety record.",
 "Ustekinumab blocks IL-12 and IL-23; risankizumab, mirikizumab and guselkumab block IL-23 only. They work in Crohn’s disease and ulcerative colitis, including after anti-TNF failure. In the SEQUENCE trial, risankizumab outperformed ustekinumab for endoscopic remission in Crohn’s after anti-TNF failure.",
 [("For", "Moderate to severe Crohn’s disease and ulcerative colitis"),
  ("Works", "Effective, including in people who didn’t respond to anti-TNF drugs"),
  BIO_COST,
  ("Kicks in", "4 to 12 weeks"),
  ("Dose", "IV induction (1 to 3 infusions), then under-skin injections every 4 to 8 weeks depending on the drug"),
  ("Watch for", "Colds, headache, injection-site reactions; liver tests with risankizumab")],
 "Signal blockers with a long interval.",
 ["Ustekinumab: Stelara and biosimilars. Risankizumab: Skyrizi. Mirikizumab: Omvoh. Guselkumab: Tremfya"],
 "IL-23 drives Th17 cells that fuel gut inflammation; blocking it calms the process.",
 ["Crohn’s disease", "Ulcerative colitis", "Also psoriasis and psoriatic arthritis"],
 "Generally well tolerated.",
 [g(C, ["Colds and sore throat", "Headache", "Tiredness", "Injection-site reactions"]), g(U, ["Raised liver tests (risankizumab in Crohn’s)", "Infections"]), g(R, ["Serious infections", "Allergic reactions"])],
 ["Fever or signs of serious infection", "Yellow skin or dark urine"],
 BIO_TIPS,
 [("What is the difference between ustekinumab and risankizumab?", "Ustekinumab blocks IL-12 and IL-23; risankizumab blocks IL-23 only. In Crohn’s after anti-TNF failure, risankizumab gave higher endoscopic remission in a head-to-head trial."),
  ("How often are the injections?", "Every 4 to 8 weeks after induction, depending on the drug."),
  ("Are IL-23 biologics safe?", "They have a good safety record, with low rates of serious infection, but still need screening and monitoring.")],
 [CCA, ("PBS: Ustekinumab", PBS + "ustekinumab"), ("PBS: Risankizumab", PBS + "risankizumab")], REL)

med("upadacitinib", "Upadacitinib (Rinvoq) and JAK Inhibitors for Crohn's and Colitis",
 "Upadacitinib and other JAK inhibitors (tofacitinib, filgotinib) for IBD explained: fast-acting tablets, high-dose induction, clot, shingles and cholesterol risks, and pregnancy.",
 "Upadacitinib and JAK inhibitors", "Upadacitinib",
 [("s", "JAK inhibitor (small molecule)"), ("l", "Prescription only (S4), specialist")],
 "A once-daily tablet that works fast for moderate to severe Crohn’s and colitis, with specific risks that need monitoring.",
 "JAK inhibitors block signalling inside immune cells. Upadacitinib works quickly, often within weeks, in Crohn’s disease and ulcerative colitis, including after biologics fail. Risks include shingles, raised cholesterol, blood clots and, in older people with heart risks, cardiovascular events. It must be avoided in pregnancy.",
 [("For", "Moderate to severe Crohn’s disease and ulcerative colitis (often after a biologic)"),
  ("Works", "Fast and effective"),
  BIO_COST,
  ("Kicks in", "Days to weeks"),
  ("Dose", "Upadacitinib 45 mg daily for 8 to 12 weeks, then 15 to 30 mg daily"),
  ("Watch for", "Acne, shingles, raised cholesterol, infections")],
 "Fast tablet, careful monitoring.",
 ["Upadacitinib: Rinvoq. Tofacitinib: Xeljanz (colitis). Filgotinib: Jyseleca (colitis)"],
 "They inhibit Janus kinase enzymes that relay cytokine signals inside immune cells.",
 ["Crohn’s disease", "Ulcerative colitis", "Also rheumatoid arthritis, eczema and other inflammatory conditions"],
 "Monitoring blood counts, liver tests and cholesterol keeps it safe.",
 [g(C, ["Acne", "Colds and upper respiratory infections", "Raised cholesterol and CK", "Headache"]), g(U, ["<b>Shingles</b>", "Low blood counts"]), g(R, ["<b>Blood clots</b>", "<b>Heart attack and stroke</b> (higher in older smokers with heart risk)", "Serious infections, cancers"])],
 ["Calf pain, chest pain or sudden breathlessness", "Painful blistering rash", "Fever or signs of serious infection"],
 ["Get the non-live shingles vaccine (Shingrix) before starting if possible.", "Use effective contraception: avoid in pregnancy and for 4 weeks after stopping.", "Blood tests including cholesterol at baseline and during treatment."],
 [("How fast does upadacitinib work?", "Often within days to a few weeks, faster than most biologics."),
  ("Is upadacitinib safe in pregnancy?", "No. It should be avoided in pregnancy, with contraception during and for 4 weeks after treatment."),
  ("Why does upadacitinib cause shingles?", "JAK inhibitors weaken antiviral defences. The shingles vaccine before starting reduces the risk.")],
 [CCA, ("PBS: Upadacitinib", PBS + "upadacitinib")], REL)
